#include <iostream>
using namespace std;

// Dependency interface — abstract base class with a pure virtual method
class OrderRepository {
public:
    virtual void save(int orderId) = 0;
    virtual ~OrderRepository() {}
};

class PostgresOrderRepository : public OrderRepository {
public:
    void save(int orderId) override {
        cout << "Saved order " << orderId << " to Postgres" << endl;
    }
};

class InMemoryOrderRepository : public OrderRepository {
public:
    void save(int orderId) override {
        cout << "Saved order " << orderId << " to memory (no real database touched)" << endl;
    }
};

// BEFORE — the exact bug the teammate found, constructs its own dependency
class BrokenOrderService {
private:
    OrderRepository* repository;
public:
    BrokenOrderService() {
        repository = new PostgresOrderRepository();   // decided internally, can never be overridden
    }
    void placeOrder(int orderId) { repository->save(orderId); }
};

// AFTER — constructor injection, the standard and most common form
class OrderService {
private:
    OrderRepository* repository;
public:
    OrderService(OrderRepository* repository) {   // received from outside, never constructed here
        this->repository = repository;
    }
    void placeOrder(int orderId) { repository->save(orderId); }
};

// Production composition root — the ONE place that decides which concrete class to use
class AppConfig {
public:
    OrderService buildOrderService() {
        OrderRepository* repository = new PostgresOrderRepository();
        return OrderService(repository);   // injected here, once, in one obvious place
    }
};

int main() {
    // Production wiring — the composition root decides the real dependency
    AppConfig config;
    OrderService service = config.buildOrderService();
    service.placeOrder(101);

    // Test wiring — the teammate's original problem, now actually solved
    InMemoryOrderRepository fakeRepository;
    OrderService testService(&fakeRepository);   // no real database touched, ever
    testService.placeOrder(202);

    // Manual wiring above is the same idea DI frameworks (Spring in Java,
    // Boost.DI in C++) automate: one composition root decides concrete
    // classes, every other class just declares what it needs.

    return 0;
}
